const expenses = $input.all().map(item => item.json);

// Current month in India
const now = new Date(
  new Date().toLocaleString("en-US", {
    timeZone: "Asia/Kolkata"
  })
);

const year = now.getFullYear();
const month = now.getMonth();

// Filter expenses for the current month
const monthlyExpenses = expenses.filter(expense => {
  const rawDate = expense.Date ?? expense.date;

  if (!rawDate) return false;

  // Read YYYY-MM-DD without timezone shifting the date
  const match = String(rawDate).match(/^(\d{4})-(\d{2})-(\d{2})/);

  if (!match) return false;

  const expenseYear = Number(match[1]);
  const expenseMonth = Number(match[2]) - 1;

  return expenseYear === year && expenseMonth === month;
});

// Calculate total spending
const total = monthlyExpenses.reduce((sum, expense) => {
  const amount = Number(expense.Amount ?? expense.amount ?? 0);
  return sum + (Number.isFinite(amount) ? amount : 0);
}, 0);

// Calculate category-wise spending
const categories = {};

for (const expense of monthlyExpenses) {
  const category =
    String(expense.Category ?? expense.category ?? "Other").trim() ||
    "Other";

  const amount = Number(expense.Amount ?? expense.amount ?? 0);

  if (Number.isFinite(amount)) {
    categories[category] = (categories[category] || 0) + amount;
  }
}

// Format category totals
const categoryLines = Object.entries(categories)
  .sort((a, b) => b[1] - a[1])
  .map(([category, amount]) =>
    `• ${category}: ₹${amount.toFixed(2)}`
  )
  .join("\n");

// Format month name
const monthName = new Intl.DateTimeFormat("en-IN", {
  month: "long",
  year: "numeric",
  timeZone: "Asia/Kolkata"
}).format(new Date());

// Build Telegram message
const report = [
  `📊 MONTHLY EXPENSE REPORT`,
  `📅 ${monthName}`,
  ``,
  `💰 Total Spent: ₹${total.toFixed(2)}`,
  `🧾 Number of Expenses: ${monthlyExpenses.length}`,
  ``,
  `📂 CATEGORY BREAKDOWN`,
  categoryLines || "No expenses recorded this month.",
  ``,
  `Report generated automatically by your Expense Tracker.`
].join("\n");

return [
  {
    json: {
      report,
      total,
      expenseCount: monthlyExpenses.length,
      categoryBreakdown: categories,
      reportMonth: monthName
    }
  }
];
